// out/design/atax_v4/design_point.json. Do not edit: run `pixi run gen-gvsoc
// out/design/atax_v4/design_point.json` again.
// The task list atax_v4 on snRuntime: core 0 runs the DMA and the accelerator
// atax; the SNAX waits as the lowering places them, the DMA's on dependences
// only, a barrier where another core goes on. One function per core, a straight
// line; the window from main's entry to forge_check()'s. Built with
// -DFORGE_QUIET: every start waited at once, each section marked in CSR 0x7c5
// (obs_marks.json), no prints.

#include "snrt.h"

#include "data.h"
#include "atax_csr.h"
#include "streamer_atax_csr_addr_map.h"

// Each accelerator task's counter, stored right after the wait that covers it
static uint32_t forge_counter[1];

// Core 0: the DMA and the accelerator atax
static __attribute__((noinline)) int forge_core_0(void) {
#ifdef FORGE_QUIET
    write_csr(0x7c5, 1);  // dma load_A
#endif  // FORGE_QUIET
    snrt_dma_start_1d((void *)0x10000000, A, 64);
#ifdef FORGE_QUIET
    snrt_dma_wait_all();
#endif  // FORGE_QUIET
#ifdef FORGE_QUIET
    write_csr(0x7c5, 2);  // dma load_x
#endif  // FORGE_QUIET
    snrt_dma_start_1d((void *)0x10000040, x, 64);
#ifdef FORGE_QUIET
    snrt_dma_wait_all();
#endif  // FORGE_QUIET
#ifdef FORGE_QUIET
    write_csr(0x7c5, 3);  // streamer config atax
#endif  // FORGE_QUIET
    csrw_ss(ATAX_BASE_PTR_READER_0_LOW, 0x10000000);
    csrw_ss(ATAX_BASE_PTR_READER_0_HIGH, 0);
    csrw_ss(ATAX_S_STRIDE_READER_0_0, 8);
    csrw_ss(ATAX_T_BOUND_READER_0_0, 1);
    csrw_ss(ATAX_T_BOUND_READER_0_1, 4);
    csrw_ss(ATAX_T_STRIDE_READER_0_0, 8);
    csrw_ss(ATAX_T_STRIDE_READER_0_1, 8);
    csrw_ss(ATAX_BASE_PTR_READER_1_LOW, 0x10000040);
    csrw_ss(ATAX_BASE_PTR_READER_1_HIGH, 0);
    csrw_ss(ATAX_S_STRIDE_READER_1_0, 8);
    csrw_ss(ATAX_T_BOUND_READER_1_0, 1);
    csrw_ss(ATAX_T_BOUND_READER_1_1, 4);
    csrw_ss(ATAX_T_STRIDE_READER_1_0, 8);
    csrw_ss(ATAX_T_STRIDE_READER_1_1, 0);
    csrw_ss(ATAX_BASE_PTR_WRITER_0_LOW, 0x10000080);
    csrw_ss(ATAX_BASE_PTR_WRITER_0_HIGH, 0);
    csrw_ss(ATAX_S_STRIDE_WRITER_0_0, 8);
    csrw_ss(ATAX_T_BOUND_WRITER_0_0, 2);
    csrw_ss(ATAX_T_BOUND_WRITER_0_1, 1);
    csrw_ss(ATAX_T_STRIDE_WRITER_0_0, 16);
    csrw_ss(ATAX_T_STRIDE_WRITER_0_1, 32);
#ifdef FORGE_QUIET
    write_csr(0x7c5, 4);  // acc config atax
#endif  // FORGE_QUIET
    csrw_ss(ATAX_RW_JOBS, 1);
    csrw_ss(ATAX_RW_SUM_JOB_BEATS, 2);
    csrw_ss(ATAX_RW_MAC_JOB_BEATS, 8);
    csrw_ss(ATAX_RW_MAC_ROWS, 2);
#ifndef FORGE_QUIET
    snrt_dma_wait_all();
#endif  // FORGE_QUIET
#ifdef FORGE_QUIET
    write_csr(0x7c5, 5);  // run atax
#endif  // FORGE_QUIET
    csrw_ss(ATAX_STREAMER_START_CSR, 1);
    csrw_ss(ATAX_RW_START, 1);
    while (csrr_ss(ATAX_RO_STATUS) & 1) {
    }
    while (csrr_ss(ATAX_STREAMER_BUSY_CSR)) {
    }
    forge_counter[0] = csrr_ss(ATAX_RO_BUSY_COUNTER);
#ifdef FORGE_QUIET
    write_csr(0x7c5, 6);  // dma store_y
#endif  // FORGE_QUIET
    snrt_dma_start_1d(y, (void *)0x10000080, 64);
    snrt_dma_wait_all();
    return 0;
}

// The window's end, then the self-check
static __attribute__((noinline)) int forge_check(uint32_t t0) {
    uint32_t cycles = snrt_mcycle() - t0;
#ifdef FORGE_QUIET
    write_csr(0x7c5, 7);  // check
    (void)cycles;
#endif  // FORGE_QUIET
#ifndef FORGE_QUIET
    printf("forge cycles: %u\n", cycles);
#endif  // FORGE_QUIET
    int err = 0;
    int data_errors = 0;
    for (uint32_t i = 0; i < 8; i++) {
        if (((volatile int32_t *)y)[i] != y_golden[i]) {
            data_errors++;
        }
    }
    err += data_errors;
#ifndef FORGE_QUIET
    printf("forge data: %d errors (%u words)\n", data_errors, 8u);
#endif  // FORGE_QUIET
#ifndef FORGE_QUIET
    printf("forge counter tmp2_mult_atax: %u\n", forge_counter[0]);
#endif  // FORGE_QUIET
    err += forge_counter[0] < 8;
#ifndef FORGE_QUIET
    printf("forge errors: %d\n", err);
#endif  // FORGE_QUIET
    return err;
}

// Each core's function, by snrt_cluster_core_idx()
static int (*const forge_cores[1])(void) = {forge_core_0};

int main() {
    uint32_t t0 = snrt_mcycle();
    uint32_t core = snrt_cluster_core_idx();
    int err = forge_cores[core]();
    if (core == 0) {
        err += forge_check(t0);
    }
    return err;
}
